# ---------------------------------------------------------
# Load saved model safely
# ---------------------------------------------------------
@st.cache_resource
def load_pipeline(path):
    return joblib.load(path)

if not PIPELINE_FILE.exists():
    st.error("The saved model file was not found. Put final_mlp_pipeline.joblib in the same folder as app.py.")
    st.stop()

try:
    model_pipeline = load_pipeline(str(PIPELINE_FILE))
except Exception as exc:
    st.error("The model pipeline could not be loaded. Check that transformers.py is in the project folder and that the required packages are installed.")
    st.caption(f"Technical detail: {exc}")
    st.stop()

feature_columns = list(model_pipeline.feature_names_in_)
categorical_features = ["loc_mn", "dc_mn"]
numeric_features = [feature for feature in feature_columns if feature not in categorical_features]
crime_features = [feature for feature in numeric_features if feature not in ["latitude", "longitude", "start_year"]]

preprocessor = model_pipeline.named_steps["preprocessor"]
categorical_pipeline = next(
    transformer for name, transformer, columns in preprocessor.transformers_ if name == "cat"
)
encoder = categorical_pipeline.named_steps["encoder"]
loc_options = list(encoder.categories_[0])
dc_options = list(encoder.categories_[1])


def readable_label(feature):
    return feature.replace("_", " ").title()


def feature_icon(feature):
    icons = {
        "loc_mn": "🏢", "dc_mn": "🏛️",
        "latitude": "📍", "longitude": "🧭", "start_year": "📅",
        "murder": "🎯", "attempted_murder": "🚔", "rape": "👤",
        "sexual_assault": "🛡️", "assault_gbh": "🤕", "kidnapping": "🚨",
        "arson": "🔥", "burglary_res": "🏠", "burglary_nonres": "🏢",
        "theft": "👜", "other_theft": "🔎", "robbery": "🚨",
    }
    return icons.get(feature, "📊")


def number_input_with_icon(feature, label=None, **kwargs):
    field_label = label or readable_label(feature)
    st.markdown(f'<div class="custom-field-label">{field_label}</div>', unsafe_allow_html=True)
    icon_col, input_col = st.columns([0.115, 0.885], gap="small", vertical_alignment="center")
    with icon_col:
        st.markdown(
            f'<div class="field-icon" title="{field_label}">{feature_icon(feature)}</div>',
            unsafe_allow_html=True,
        )
    with input_col:
        return st.number_input(field_label, label_visibility="collapsed", **kwargs)

def selectbox_with_icon(feature, label, options, **kwargs):
    st.markdown(f'<div class="custom-field-label">{label}</div>', unsafe_allow_html=True)
    icon_col, input_col = st.columns([0.115, 0.885], gap="small", vertical_alignment="center")
    with icon_col:
        st.markdown(
            f'<div class="field-icon" title="{label}">{feature_icon(feature)}</div>',
            unsafe_allow_html=True,
        )
    with input_col:
        return st.selectbox(label, options, label_visibility="collapsed", **kwargs)

